import { clamp } from '@/utils/math';

/**
 * Reference RSSI (dBm) measured at 1 metre for a typical BLE radio when the
 * advertisement does not carry a calibrated TX power. Real beacons vary; this
 * is a reasonable default for phones/earbuds.
 */
const DEFAULT_RSSI_AT_ONE_METER = -59;

/**
 * Environmental path-loss exponent. 2.0 = free space; 2.7-3.5 indoors with
 * walls/bodies. 2.5 is a decent all-round compromise for the "distance" readout.
 */
const PATH_LOSS_EXPONENT = 2.5;

/**
 * Estimates distance in metres from RSSI using the log-distance path-loss model:
 *
 *   distance = 10 ^ ((referenceRssi - rssi) / (10 * n))
 *
 * When the advertisement includes a calibrated `txPower` (RSSI at 1 m) we use
 * it; otherwise we fall back to {@link DEFAULT_RSSI_AT_ONE_METER}.
 *
 * The result is a coarse estimate — RSSI is noisy and multipath-prone — so it
 * is clamped to a sane range and rounded to a friendly precision.
 */
export function rssiToDistanceMeters(rssi: number, txPower?: number): number {
  if (!Number.isFinite(rssi) || rssi === 0) {
    return 0;
  }

  const referenceRssi = txPower != null && txPower < 0 ? txPower : DEFAULT_RSSI_AT_ONE_METER;
  const ratio = (referenceRssi - rssi) / (10 * PATH_LOSS_EXPONENT);
  const distance = Math.pow(10, ratio);

  const bounded = clamp(distance, 0, 200);
  return Math.round(bounded * 100) / 100;
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function normalizeScore(value: number): number {
  return clamp(value, 0, 100);
}

import { CellReading, SignalQuality } from '@/types';
import { clamp } from '@/utils/math';

/**
 * Classifies serving-cell signal power into a human friendly quality level.
 *
 * LTE/NR expose RSRP (Reference Signal Received Power) which is the most
 * meaningful metric; older radios only report RSSI. Thresholds follow the
 * commonly used carrier ranges:
 *   RSRP  >= -80  excellent, -90 good, -100 fair, -110 poor, below very poor
 *   RSSI  >= -65  excellent, -75 good, -85 fair, -95 poor
 */
export function classifySignalQuality(reading: CellReading): SignalQuality {
  const rsrp = reading.rsrp;
  const rssi = reading.rssi;

  if (rsrp != null) {
    return fromThresholds(rsrp, [-80, -90, -100, -110]);
  }

  if (rssi != null) {
    return fromThresholds(rssi, [-65, -75, -85, -95]);
  }

  return { level: 'unknown', label: 'Unknown', bars: 0 };
}

function fromThresholds(
  value: number,
  [excellent, good, fair, poor]: [number, number, number, number],
): SignalQuality {
  if (value >= excellent) {
    return { level: 'excellent', label: 'Excellent', bars: 100 };
  }
  if (value >= good) {
    return { level: 'good', label: 'Good', bars: 80 };
  }
  if (value >= fair) {
    return { level: 'fair', label: 'Fair', bars: 55 };
  }
  if (value >= poor) {
    return { level: 'poor', label: 'Poor', bars: 30 };
  }
  // Linearly fade the bar between the poor threshold and a -140 dBm floor.
  const bars = clamp(Math.round(((value - -140) / (poor - -140)) * 30), 0, 30);
  return { level: 'poor', label: 'Very Poor', bars };
}

const BYTE_UNITS = ['B', 'KB', 'MB', 'GB', 'TB'] as const;

/** Formats a byte count using binary (1024) units, e.g. 1536 -> "1.5 KB". */
export function formatBytes(bytes: number, fractionDigits = 1): string {
  if (!Number.isFinite(bytes) || bytes <= 0) {
    return '0 B';
  }

  const exponent = Math.min(
    Math.floor(Math.log(bytes) / Math.log(1024)),
    BYTE_UNITS.length - 1,
  );
  const value = bytes / 1024 ** exponent;
  const digits = exponent === 0 ? 0 : fractionDigits;
  return `${value.toFixed(digits)} ${BYTE_UNITS[exponent]}`;
}

/** Formats a byte-per-second rate, e.g. 2048 -> "2.0 KB/s". */
export function formatRate(bytesPerSecond: number): string {
  return `${formatBytes(bytesPerSecond)}/s`;
}

import { BearingEstimate, BearingSample } from '@/types';
import { rssiToDistanceMeters } from '@/utils/distance';
import { clamp } from '@/utils/math';

const MIN_SAMPLES = 8;
const BUCKET_DEGREES = 15;

/**
 * Estimates the bearing to a Bluetooth device from a set of (heading, rssi)
 * samples gathered while the user slowly rotates/sweeps the phone.
 *
 * Intuition: signal is strongest when the phone's back is pointed at (or the
 * body is not blocking) the device. We bucket samples by heading, average RSSI
 * per bucket, and take the strongest bucket as the bearing. Confidence grows
 * with the RSSI contrast between the best and worst directions and with how
 * many directions were actually sampled.
 *
 * This is deliberately heuristic — RSSI direction-finding on a single antenna
 * is approximate — and mirrors the "sampling data, please move your device"
 * radar UX rather than promising true angle-of-arrival.
 */
export function estimateBearing(samples: BearingSample[]): BearingEstimate {
  const latestRssi = samples.length > 0 ? samples[samples.length - 1].rssi : -100;
  const distanceMeters = rssiToDistanceMeters(latestRssi);

  if (samples.length < MIN_SAMPLES) {
    return {
      bearing: null,
      confidence: 0,
      distanceMeters,
      sampleCount: samples.length,
    };
  }

  const bucketCount = Math.ceil(360 / BUCKET_DEGREES);
  const sums = new Array<number>(bucketCount).fill(0);
  const counts = new Array<number>(bucketCount).fill(0);

  for (const sample of samples) {
    const normalized = ((sample.heading % 360) + 360) % 360;
    const bucket = Math.floor(normalized / BUCKET_DEGREES) % bucketCount;
    sums[bucket] += sample.rssi;
    counts[bucket] += 1;
  }

  let bestBucket = -1;
  let bestAvg = -Infinity;
  let worstAvg = Infinity;
  let populatedBuckets = 0;

  for (let i = 0; i < bucketCount; i += 1) {
    if (counts[i] === 0) {
      continue;
    }
    populatedBuckets += 1;
    const avg = sums[i] / counts[i];
    if (avg > bestAvg) {
      bestAvg = avg;
      bestBucket = i;
    }
    if (avg < worstAvg) {
      worstAvg = avg;
    }
  }

  if (bestBucket < 0) {
    return { bearing: null, confidence: 0, distanceMeters, sampleCount: samples.length };
  }

  const bearing = bestBucket * BUCKET_DEGREES + BUCKET_DEGREES / 2;

  // Contrast: a >= 20 dB spread across directions is a strong directional cue.
  const contrast = clamp((bestAvg - worstAvg) / 20, 0, 1);
  // Coverage: reward sampling many distinct directions (up to ~2/3 of buckets).
  const coverage = clamp(populatedBuckets / (bucketCount * 0.66), 0, 1);
  const confidence = Math.round(contrast * coverage * 100) / 100;

  return {
    bearing,
    confidence,
    distanceMeters,
    sampleCount: samples.length,
  };
}

import { CellReading, GhostAssessment, TowerRecord } from '@/types';
import { normalizeScore } from '@/utils/math';

const SIGNAL_SPIKE_THRESHOLD_DB = 25;
const RAPID_CHURN_WINDOW_MS = 10 * 60 * 1000;
const RAPID_CHURN_TOWER_COUNT = 4;

export function assessGhostTower(
  reading: CellReading,
  recentReadings: CellReading[],
  tower?: TowerRecord,
): GhostAssessment {
  let score = 0;
  const reasons: string[] = [];

  if (!tower) {
    score += 35;
    reasons.push('Tower ID not found in trusted tower datasets.');
  }

  const last = recentReadings.at(-1);
  if (
    last?.rsrp != null &&
    reading.rsrp != null &&
    Math.abs(reading.rsrp - last.rsrp) >= SIGNAL_SPIKE_THRESHOLD_DB
  ) {
    score += 25;
    reasons.push('Signal power changed too abruptly for normal mobility.');
  }

  const now = reading.timestamp;
  const recentCids = new Set(
    recentReadings
      .filter((item) => now - item.timestamp <= RAPID_CHURN_WINDOW_MS)
      .map((item) => item.cid)
      .filter((value): value is number => typeof value === 'number'),
  );

  if (reading.cid) {
    recentCids.add(reading.cid);
  }

  if (recentCids.size >= RAPID_CHURN_TOWER_COUNT) {
    score += 20;
    reasons.push('Rapid cell-ID churn suggests possible rogue base station behavior.');
  }

  if ((reading.neighboringCellCount ?? 0) <= 1 && (reading.rsrp ?? -140) > -80) {
    score += 20;
    reasons.push('Strong serving signal with no normal neighboring cells detected.');
  }

  // An IMSI catcher frequently keeps the same PCI/CID pair while the operator
  // identity (MCC/MNC) or LAC/TAC flips versus what we have seen historically.
  const historicalForCid = recentReadings.filter(
    (item) => item.cid != null && item.cid === reading.cid,
  );
  const mncMismatch = historicalForCid.some(
    (item) => item.mnc != null && reading.mnc != null && item.mnc !== reading.mnc,
  );
  if (mncMismatch) {
    score += 25;
    reasons.push('Same cell ID observed under a different operator (MNC) — spoofing indicator.');
  }

  // Downgrade attacks force a modern handset onto 2G/GSM to strip encryption.
  if (reading.radioType === 'GSM') {
    const hasSeenModern = recentReadings.some(
      (item) => item.radioType === 'LTE' || item.radioType === 'NR' || item.radioType === 'WCDMA',
    );
    if (hasSeenModern) {
      score += 20;
      reasons.push('Unexpected downgrade to 2G/GSM after using LTE/5G — possible downgrade attack.');
    }
  }

  const normalized = normalizeScore(score);
  return {
    score: normalized,
    isLikelyGhost: normalized >= 60,
    reasons,
  };
}

import { AppTrafficSample, TrafficAnomaly, TrafficSnapshot } from '@/types';
import { formatBytes, formatRate } from '@/utils/format';

export interface AnomalyThresholds {
  /** Upload rate (bytes/s) above which a sustained burst is flagged. */
  uploadRateBytesPerSecond: number;
  /**
   * Ratio of upload to download over a window above which traffic is
   * considered exfiltration-like (phones normally download far more than they
   * upload).
   */
  uploadDownloadRatio: number;
  /** Per-window transmit volume (bytes) that is notable on its own. */
  largeUploadBytes: number;
}

export const DEFAULT_THRESHOLDS: AnomalyThresholds = {
  uploadRateBytesPerSecond: 512 * 1024, // 512 KB/s sustained upload
  uploadDownloadRatio: 3,
  largeUploadBytes: 5 * 1024 * 1024, // 5 MB in a single sampling window
};

/**
 * Evaluates a single traffic snapshot for device-wide anomalies. Anomalies are
 * heuristic signals of "unusual" outbound activity, not proof of compromise.
 */
export function detectDeviceAnomalies(
  snapshot: TrafficSnapshot,
  thresholds: AnomalyThresholds = DEFAULT_THRESHOLDS,
): TrafficAnomaly[] {
  const anomalies: TrafficAnomaly[] = [];

  if (snapshot.txBytesPerSecond >= thresholds.uploadRateBytesPerSecond) {
    anomalies.push({
      id: `upload-rate-${snapshot.timestamp}`,
      timestamp: snapshot.timestamp,
      severity: 'warning',
      title: 'High sustained upload rate',
      detail: `Uploading at ${formatRate(snapshot.txBytesPerSecond)}, above the ${formatRate(
        thresholds.uploadRateBytesPerSecond,
      )} threshold.`,
    });
  }

  if (snapshot.txDeltaBytes >= thresholds.largeUploadBytes) {
    anomalies.push({
      id: `upload-volume-${snapshot.timestamp}`,
      timestamp: snapshot.timestamp,
      severity: 'warning',
      title: 'Large data upload',
      detail: `${formatBytes(snapshot.txDeltaBytes)} sent in a single interval.`,
    });
  }

  // Only judge the ratio once there is meaningful traffic, otherwise idle
  // keep-alives produce noise.
  const meaningfulTraffic = snapshot.txDeltaBytes > 256 * 1024;
  if (
    meaningfulTraffic &&
    snapshot.txDeltaBytes > snapshot.rxDeltaBytes * thresholds.uploadDownloadRatio
  ) {
    anomalies.push({
      id: `upload-ratio-${snapshot.timestamp}`,
      timestamp: snapshot.timestamp,
      severity: 'critical',
      title: 'Outbound-heavy traffic',
      detail: `Sent ${formatBytes(snapshot.txDeltaBytes)} vs received ${formatBytes(
        snapshot.rxDeltaBytes,
      )} — unusual for normal usage and consistent with data exfiltration.`,
    });
  }

  return anomalies;
}

/**
 * Flags individual apps whose upload volume over the window is dominant or
 * outbound-heavy. Helps attribute a device-wide anomaly to a specific app.
 */
export function detectAppAnomalies(
  deltas: AppTrafficSample[],
  thresholds: AnomalyThresholds = DEFAULT_THRESHOLDS,
): TrafficAnomaly[] {
  const anomalies: TrafficAnomaly[] = [];

  for (const app of deltas) {
    const outboundHeavy =
      app.txBytes > 256 * 1024 && app.txBytes > app.rxBytes * thresholds.uploadDownloadRatio;
    const largeUpload = app.txBytes >= thresholds.largeUploadBytes;

    if (!outboundHeavy && !largeUpload) {
      continue;
    }

    const name = app.appLabel ?? app.packageName ?? `uid ${app.uid}`;
    anomalies.push({
      id: `app-${app.uid}-${app.timestamp}`,
      timestamp: app.timestamp,
      severity: largeUpload && outboundHeavy ? 'critical' : 'warning',
      title: `Unusual activity: ${name}`,
      detail: `Sent ${formatBytes(app.txBytes)} / received ${formatBytes(app.rxBytes)}.`,
      packageName: app.packageName,
      appLabel: app.appLabel,
    });
  }

  return anomalies;
}

import { BleDevice, BleDeviceType, BleSignalSample } from '@/types';
import { NativeBleDevice } from '@/native/SignalTraceNative';
import { rssiToDistanceMeters } from '@/utils/distance';

const MAX_HISTORY = 90;

function parseType(value?: string): BleDeviceType {
  switch (value) {
    case 'BR/EDR':
    case 'LE':
    case 'BR/EDR/LE':
      return value;
    default:
      return 'UNKNOWN';
  }
}

/**
 * Folds a freshly received advertisement into the existing device record (or
 * creates one), appending to the bounded RSSI history and recomputing the
 * distance estimate. Pure: returns a new object, never mutates `existing`.
 */
export function mergeAdvertisement(
  existing: BleDevice | undefined,
  raw: NativeBleDevice,
): BleDevice {
  const sample: BleSignalSample = { timestamp: raw.timestamp, rssi: raw.rssi };
  const history = [...(existing?.history ?? []), sample].slice(-MAX_HISTORY);

  return {
    address: raw.address,
    // Keep a previously learned name if this advertisement omitted it.
    name: raw.name ?? existing?.name,
    rssi: raw.rssi,
    txPower: raw.txPower ?? existing?.txPower,
    type: parseType(raw.type),
    bondState: raw.bondState ?? existing?.bondState ?? 'Unbound',
    connectable: raw.connectable ?? existing?.connectable ?? true,
    manufacturerId: raw.manufacturerId ?? existing?.manufacturerId,
    manufacturerData: raw.manufacturerData ?? existing?.manufacturerData,
    firstSeenAt: existing?.firstSeenAt ?? raw.timestamp,
    lastSeenAt: raw.timestamp,
    distanceMeters: rssiToDistanceMeters(raw.rssi, raw.txPower ?? existing?.txPower),
    history,
  };
}

/** Sorts devices strongest-signal-first for the nearby list. */
export function sortByStrength(devices: BleDevice[]): BleDevice[] {
  return [...devices].sort((a, b) => b.rssi - a.rssi);
}

/** Drops devices not seen within `staleMs` so the live list self-prunes. */
export function pruneStale(devices: BleDevice[], now: number, staleMs: number): BleDevice[] {
  return devices.filter((device) => now - device.lastSeenAt <= staleMs);
}

import { AppTrafficSample, TrafficSample, TrafficSnapshot } from '@/types';
import { trafficModule } from '@/native/SignalTraceNative';

/**
 * Reads cumulative device-wide byte counters. Uses the native TrafficStats
 * bridge when available; otherwise returns undefined so the caller can degrade
 * gracefully (JS has no access to raw interface counters on Android).
 */
export async function sampleDeviceTraffic(): Promise<TrafficSample | undefined> {
  if (!trafficModule) {
    return undefined;
  }

  try {
    const sample = await trafficModule.getDeviceTraffic();
    // TrafficStats returns -1 (UNSUPPORTED) on some devices/counters.
    if (sample.rxBytes < 0 || sample.txBytes < 0) {
      return undefined;
    }
    return sample;
  } catch {
    return undefined;
  }
}

/**
 * Reads per-app traffic for a time window. Requires PACKAGE_USAGE_STATS special
 * access; resolves to an empty list when unavailable or ungranted.
 */
export async function sampleAppTraffic(
  startMillis: number,
  endMillis: number,
): Promise<AppTrafficSample[]> {
  if (!trafficModule) {
    return [];
  }

  try {
    if (!(await trafficModule.hasUsageAccess())) {
      return [];
    }
    return await trafficModule.getAppTraffic(startMillis, endMillis);
  } catch {
    return [];
  }
}

export async function hasUsageAccess(): Promise<boolean> {
  if (!trafficModule) {
    return false;
  }
  try {
    return await trafficModule.hasUsageAccess();
  } catch {
    return false;
  }
}

export async function requestUsageAccess(): Promise<void> {
  if (!trafficModule) {
    return;
  }
  try {
    await trafficModule.requestUsageAccess();
  } catch {
    // Opening Settings is best-effort; ignore failures.
  }
}

/**
 * Computes throughput and deltas between two cumulative samples. Handles the
 * counter reset that happens on reboot (current < previous) by treating the
 * window as if it started at the current values, avoiding negative rates.
 */
export function computeTrafficSnapshot(
  previous: TrafficSample,
  current: TrafficSample,
  baseline: { rx: number; tx: number },
): TrafficSnapshot {
  const elapsedMs = current.timestamp - previous.timestamp;
  const elapsedSeconds = elapsedMs > 0 ? elapsedMs / 1000 : 1;

  const counterReset = current.rxBytes < previous.rxBytes || current.txBytes < previous.txBytes;
  const rxDelta = counterReset ? 0 : current.rxBytes - previous.rxBytes;
  const txDelta = counterReset ? 0 : current.txBytes - previous.txBytes;

  return {
    timestamp: current.timestamp,
    rxDeltaBytes: rxDelta,
    txDeltaBytes: txDelta,
    rxBytesPerSecond: Math.max(0, Math.round(rxDelta / elapsedSeconds)),
    txBytesPerSecond: Math.max(0, Math.round(txDelta / elapsedSeconds)),
    totalRxBytes: Math.max(0, current.rxBytes - baseline.rx),
    totalTxBytes: Math.max(0, current.txBytes - baseline.tx),
  };
}

import { NativeEventEmitter, NativeModules } from 'react-native';
import { AppTrafficSample, TrafficSample } from '@/types';

/**
 * Typed access to the SignalTrace native Android modules. Both modules are
 * implemented in Kotlin under android/app/src/main/java/com/signaltrace and
 * registered by SignalTracePackage. When the JS runs outside a build that
 * includes the native side (e.g. Metro on a plain device, or unit tests), the
 * modules are `undefined`; every consumer must guard for that and fall back.
 */

export interface NativeCellReading {
  radioType?: string;
  registered?: boolean;
  mcc?: number;
  mnc?: number;
  lac?: number;
  tac?: number;
  cid?: number;
  pci?: number;
  arfcn?: number;
  rsrp?: number;
  rsrq?: number;
  rssi?: number;
  sinr?: number;
  neighboringCellCount?: number;
}

export interface CellScannerModule {
  /** Returns all visible cells (serving + neighboring) from TelephonyManager. */
  getCellInfo(): Promise<NativeCellReading[]>;
}

export interface TrafficModule {
  /** Device-wide cumulative rx/tx byte counters since boot (TrafficStats). */
  getDeviceTraffic(): Promise<TrafficSample>;
  /**
   * Per-app cumulative traffic over [start, end] using NetworkStatsManager.
   * Requires PACKAGE_USAGE_STATS special access; resolves to [] otherwise.
   */
  getAppTraffic(startMillis: number, endMillis: number): Promise<AppTrafficSample[]>;
  /** Whether PACKAGE_USAGE_STATS has been granted for this app. */
  hasUsageAccess(): Promise<boolean>;
  /** Opens the system Usage Access settings screen so the user can grant it. */
  requestUsageAccess(): Promise<void>;
}

/** Raw BLE advertisement payload emitted by the native scanner. */
export interface NativeBleDevice {
  address: string;
  name?: string;
  rssi: number;
  txPower?: number;
  timestamp: number;
  type?: string;
  bondState?: string;
  connectable?: boolean;
  manufacturerId?: number;
  manufacturerData?: string;
}

export interface BleScannerModule {
  isSupported(): Promise<boolean>;
  isEnabled(): Promise<boolean>;
  startScan(): Promise<boolean>;
  stopScan(): Promise<boolean>;
  addListener(eventName: string): void;
  removeListeners(count: number): void;
}

export interface OrientationModule {
  start(): Promise<boolean>;
  stop(): Promise<boolean>;
  addListener(eventName: string): void;
  removeListeners(count: number): void;
}

interface NativeModuleRegistry {
  SignalTraceCellScanner?: CellScannerModule;
  SignalTraceTraffic?: TrafficModule;
  SignalTraceBleScanner?: BleScannerModule;
  SignalTraceOrientation?: OrientationModule;
}

const modules = NativeModules as NativeModuleRegistry;

export const cellScannerModule: CellScannerModule | undefined =
  modules.SignalTraceCellScanner;

export const trafficModule: TrafficModule | undefined = modules.SignalTraceTraffic;

export const bleScannerModule: BleScannerModule | undefined = modules.SignalTraceBleScanner;

export const orientationModule: OrientationModule | undefined =
  modules.SignalTraceOrientation;

/** Native event names emitted through RCTDeviceEventEmitter. */
export const BLE_DEVICE_EVENT = 'SignalTraceBleDevice';
export const BLE_SCAN_FAILED_EVENT = 'SignalTraceBleScanFailed';
export const HEADING_EVENT = 'SignalTraceHeading';

export function createBleEmitter(): NativeEventEmitter | undefined {
  if (!bleScannerModule) {
    return undefined;
  }
  return new NativeEventEmitter(bleScannerModule as unknown as never);
}

export function createOrientationEmitter(): NativeEventEmitter | undefined {
  if (!orientationModule) {
    return undefined;
  }
  return new NativeEventEmitter(orientationModule as unknown as never);
}
